const ApiBadRequestErrorResponseBodySchema = z
  .object({
    code: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Error code',
        examples: [400],
        'x-go-name': 'Code',
      }),
    message: z
      .string()
      .openapi({
        description: 'Error message',
        examples: ['Invalid request'],
        'x-go-name': 'Message',
      }),
    status: z
      .string()
      .openapi({ description: 'Error status', examples: ['error'], 'x-go-name': 'Status' }),
  })
  .openapi({
    required: ['code', 'message', 'status'],
    'x-go-package': 'gitlab.atlasgroup.ai/twelvedata/api/route/description',
  })
  .openapi('ApiBadRequestErrorResponseBody')

