const MarketMoversResponseValueResponse = {
  description: '',
  content: {},
  headers: z.object({
    volume: {
      description: 'The trading volume of the symbol today',
      schema: z
        .preprocess(
          (val) =>
            typeof val === 'number' && Number.isSafeInteger(val)
              ? BigInt(val)
              : typeof val === 'string' && /^-?\d+$/.test(val)
                ? BigInt(val)
                : val,
          z.int64(),
        )
        .exactOptional()
        .openapi({
          description: 'The trading volume of the symbol today',
          param: { required: false },
          type: 'integer',
          format: 'int64',
          examples: [108297],
        }),
    },
    symbol: {
      description: 'The exchange symbol ticker',
      schema: z
        .string()
        .exactOptional()
        .openapi({
          description: 'The exchange symbol ticker',
          param: { required: false },
          examples: ['BSET'],
        }),
    },
    datetime: {
      description: 'The last updated datetime timestamp',
      schema: z
        .string()
        .exactOptional()
        .openapi({
          description: 'The last updated datetime timestamp',
          param: { required: false },
          examples: ['2023-10-01 12:00:00Z'],
        }),
    },
    high: {
      description: 'The highest price for the symbol today',
      schema: z
        .float64()
        .exactOptional()
        .openapi({
          description: 'The highest price for the symbol today',
          param: { required: false },
          examples: [18],
        }),
    },
    mic_code: {
      description: 'Market identifier code (MIC) under ISO 10383 standard',
      schema: z
        .string()
        .exactOptional()
        .openapi({
          description: 'Market identifier code (MIC) under ISO 10383 standard',
          param: { required: false },
          examples: ['XNAS'],
        }),
    },
    last: {
      description: 'The latest available price for the symbol today',
      schema: z
        .float64()
        .exactOptional()
        .openapi({
          description: 'The latest available price for the symbol today',
          param: { required: false },
          examples: [17.25],
        }),
    },
    low: {
      description: 'The lowest price for the symbol today',
      schema: z
        .float64()
        .exactOptional()
        .openapi({
          description: 'The lowest price for the symbol today',
          param: { required: false },
          examples: [16.5],
        }),
    },
    change: {
      description: 'The value of the change since the previous day',
      schema: z
        .float64()
        .exactOptional()
        .openapi({
          description: 'The value of the change since the previous day',
          param: { required: false },
          examples: [3.31],
        }),
    },
    name: {
      description: 'The official name of the instrument',
      schema: z
        .string()
        .exactOptional()
        .openapi({
          description: 'The official name of the instrument',
          param: { required: false },
          examples: ['Bassett Furniture Industries Inc'],
        }),
    },
    exchange: {
      description: 'Exchange where instrument is traded',
      schema: z
        .string()
        .exactOptional()
        .openapi({
          description: 'Exchange where instrument is traded',
          param: { required: false },
          examples: ['NASDAQ'],
        }),
    },
    percent_change: {
      description: 'The percentage change since the previous day',
      schema: z
        .float64()
        .exactOptional()
        .openapi({
          description: 'The percentage change since the previous day',
          param: { required: false },
          examples: [23.74462],
        }),
    },
  }),
}

